package com.example.assets_management.security.service;
import com.example.assets_management.employee.entity.Employee; import com.example.assets_management.employee.enums.UserStatus; import com.example.assets_management.employee.repository.EmployeeRepository; import com.example.assets_management.role.entity.Role; import com.example.assets_management.role.enums.RoleStatus; import com.example.assets_management.security.rbac.service.EffectivePermissionService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class CustomUserDetailsService implements UserDetailsService { private final EmployeeRepository employeeRepository; private final EffectivePermissionService permissionService; public UserDetails loadUserByUsername(String username)throws UsernameNotFoundException{ Employee u=employeeRepository.findByEmail(username).orElseThrow(()->new UsernameNotFoundException("User not found with email: "+username)); Role role=u.getRole(); Set<SimpleGrantedAuthority> a=new LinkedHashSet<>(); if(role!=null&&role.getStatus()==RoleStatus.ACTIVE)a.add(new SimpleGrantedAuthority("ROLE_"+normalize(role.getName()))); permissionService.getEffectivePermissions(u.getId()).forEach(p->a.add(new SimpleGrantedAuthority(p))); return new CustomUserDetails(u.getId(),u.getEmail(),u.getEmployeeCode(),u.getPasswordHash(),u.getCompany()==null?null:u.getCompany().getId(),u.getBranch()==null?null:u.getBranch().getId(),u.getDepartment()==null?null:u.getDepartment().getId(),role==null?null:role.getId(),role==null?null:role.getName(),u.getStatus()==UserStatus.ACTIVE,a); } private String normalize(String s){return s==null||s.isBlank()?"UNKNOWN":s.trim().toUpperCase().replaceAll("[^A-Z0-9_]+","_");} }
